[CmdletBinding()]
param([string]$ArtifactSubdirectory='mvp-trip-004/real-subset')
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$root=(Resolve-Path(Join-Path $PSScriptRoot '../../../..')).Path;$artifact=Join-Path $root ('.omo/artifacts/'+$ArtifactSubdirectory);New-Item -ItemType Directory -Force (Join-Path $artifact 'logs')|Out-Null
$db='stog_backend_test';$role='stog_r3b_'+[Guid]::NewGuid().ToString('N');$schema=$role;$password=-join((1..64)|%{'{0:x}'-f(Get-Random -Maximum 16)});$zip=Join-Path $root '.omo/local/r3-source-qa/SEMAS_store_20260630.zip';$entry='소상공인시장진흥공단_상가(상권)정보_제주_202606.csv';$media=Join-Path([IO.Path]::GetTempPath())('stog-r3b-media-'+[Guid]::NewGuid().ToString('N'));$created=$false;$backend=$null;$metadataBefore=$null;$metadataAfter=$null;$old=@{};$result=$null
function Psql([string]$sql,[switch]$Admin){$op=$env:PGPASSWORD;$ow=$env:WSLENV;try{if($Admin){$out=$sql|wsl.exe -u postgres -- psql -X -v ON_ERROR_STOP=1 -Atq -d $db -f -}else{$env:PGPASSWORD=$password;$parts=@($ow-split':'|?{$_-and($_-split'/')[0]-ne'PGPASSWORD'});$env:WSLENV=(($parts+'PGPASSWORD')-join':');$out=$sql|wsl.exe -- psql -X -v ON_ERROR_STOP=1 -Atq -h 127.0.0.1 -U $role -d $db -f -};if($LASTEXITCODE-ne0){throw'psql failed'};return($out-join"`n").Trim()}finally{$env:PGPASSWORD=$op;$env:WSLENV=$ow}}
function DecodeHex([string]$hex){$bytes=[byte[]]::new($hex.Length/2);for($i=0;$i-lt$bytes.Length;$i++){$bytes[$i]=[Convert]::ToByte($hex.Substring($i*2,2),16)};return [Text.Encoding]::UTF8.GetString($bytes)}
function StopOwned($p){if($null-ne$p-and-not$p.HasExited){& taskkill.exe /PID $p.Id /T /F 2>&1|Out-Null;[void]$p.WaitForExit(10000)};if($null-ne$p){$p.Dispose()}}
function StartBackend{$psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName='C:\Program Files\Java\jdk-17\bin\java.exe';$psi.Arguments='-jar "'+(Join-Path $root 'backend/build/libs/stog-backend-0.0.1-SNAPSHOT.jar')+'"';$psi.WorkingDirectory=$root;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$p=[Diagnostics.Process]::new();$p.StartInfo=$psi;[void]$p.Start();$deadline=[DateTime]::UtcNow.AddSeconds(120);$writer=[IO.StreamWriter]::new((Join-Path $artifact 'logs/backend.log'),$true,[Text.UTF8Encoding]::new($false));try{while($true){$left=$deadline-[DateTime]::UtcNow;if($left-le[TimeSpan]::Zero){throw'backend readiness timeout'};$task=$p.StandardOutput.ReadLineAsync();if(-not$task.Wait($left)){throw'backend readiness event timeout'};$line=$task.Result;if($null-eq$line){throw'backend exited'};$writer.WriteLine($line);if($line-match'Started StogBackendApplication'){break}}}finally{$writer.Dispose()};return $p}
try{
 if(Get-NetTCPConnection -State Listen -LocalPort 8080 -ErrorAction SilentlyContinue){throw'port 8080 occupied'}
 if((Psql "SELECT current_database()||'|'||current_setting('server_version_num');" -Admin)-ne"$db|180006"){throw'unexpected PostgreSQL'}
 $metadataBefore=Psql "SELECT md5(COALESCE(string_agg(row_to_json(x)::text,E'\n' ORDER BY x.rolname),''))FROM(SELECT * FROM pg_roles WHERE rolname<>'$role')x;SELECT md5(COALESCE(string_agg(row_to_json(x)::text,E'\n' ORDER BY x.nspname),''))FROM(SELECT n.nspname,pg_get_userbyid(n.nspowner)owner,n.nspacl::text acl FROM pg_namespace n WHERE n.nspname='public' OR n.nspname~'^task14_')x;SELECT md5(row_to_json(x)::text)FROM(SELECT datname,datdba,datacl::text acl FROM pg_database WHERE datname='$db')x;" -Admin
 Psql "BEGIN;CREATE ROLE `"$role`" LOGIN PASSWORD '$password' NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION;CREATE SCHEMA `"$schema`" AUTHORIZATION `"$role`";GRANT USAGE,CREATE ON SCHEMA `"$schema`" TO `"$role`";GRANT CONNECT ON DATABASE `"$db`" TO `"$role`";COMMIT;" -Admin|Out-Null;$created=$true;New-Item -ItemType Directory -Force $media|Out-Null
 $names=@('SPRING_DATASOURCE_URL','SPRING_DATASOURCE_USERNAME','SPRING_DATASOURCE_PASSWORD','SPRING_DATASOURCE_HIKARI_SCHEMA','SPRING_FLYWAY_DEFAULT_SCHEMA','SPRING_FLYWAY_SCHEMAS','SPRING_FLYWAY_CREATE_SCHEMAS','SERVER_ADDRESS','SERVER_PORT','STOG_MEDIA_ROOT','STOG_IMPORT_JDBC_URL','STOG_IMPORT_DB_USERNAME','STOG_IMPORT_DB_PASSWORD','STOG_IMPORT_CONFIRM_TARGET','STOG_IMPORT_ZIP','STOG_IMPORT_ENTRY','STOG_IMPORT_MAX_ROWS','JAVA_HOME');foreach($n in $names){$old[$n]=[Environment]::GetEnvironmentVariable($n,'Process')}
 $url="jdbc:postgresql://127.0.0.1:5432/$db`?currentSchema=$schema";$env:SPRING_DATASOURCE_URL=$url;$env:SPRING_DATASOURCE_USERNAME=$role;$env:SPRING_DATASOURCE_PASSWORD=$password;$env:SPRING_DATASOURCE_HIKARI_SCHEMA=$schema;$env:SPRING_FLYWAY_DEFAULT_SCHEMA=$schema;$env:SPRING_FLYWAY_SCHEMAS=$schema;$env:SPRING_FLYWAY_CREATE_SCHEMAS='false';$env:SERVER_ADDRESS='127.0.0.1';$env:SERVER_PORT='8080';$env:STOG_MEDIA_ROOT=$media
 $backend=StartBackend;StopOwned $backend;$backend=$null
 $env:STOG_IMPORT_JDBC_URL=$url;$env:STOG_IMPORT_DB_USERNAME=$role;$env:STOG_IMPORT_DB_PASSWORD=$password;$env:STOG_IMPORT_CONFIRM_TARGET=$url;$env:STOG_IMPORT_ZIP=$zip;$env:STOG_IMPORT_ENTRY=$entry;$env:STOG_IMPORT_MAX_ROWS='25';$env:JAVA_HOME='C:\Program Files\Java\jdk-17'
 Push-Location $root;try{&.\gradlew.bat -p backend --no-daemon importSemasPlaces *> (Join-Path $artifact 'logs/import-first.log');if($LASTEXITCODE-ne0){throw'first import failed'}}finally{Pop-Location}
 $first=Psql "SELECT count(*)||'|'||count(DISTINCT id)||'|'||count(DISTINCT source_key) FROM place WHERE source_type='SEMAS_STORE';";$fingerprint=Psql "SELECT md5(string_agg(source_key||':'||id::text,E'\n' ORDER BY source_key))FROM place WHERE source_type='SEMAS_STORE';"
 Push-Location $root;try{&.\gradlew.bat -p backend --no-daemon importSemasPlaces *> (Join-Path $artifact 'logs/import-repeat.log');if($LASTEXITCODE-ne0){throw'repeat import failed'}}finally{Pop-Location}
 $second=Psql "SELECT count(*)||'|'||count(DISTINCT id)||'|'||count(DISTINCT source_key) FROM place WHERE source_type='SEMAS_STORE';";$same=$fingerprint-eq(Psql "SELECT md5(string_agg(source_key||':'||id::text,E'\n' ORDER BY source_key))FROM place WHERE source_type='SEMAS_STORE';")
 $token='r3b-bounded-http-token';$sha=[Security.Cryptography.SHA256]::Create();try{$hash=(($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($token))|%{$_.ToString('x2')})-join'')}finally{$sha.Dispose()};$user=[Guid]::NewGuid();$session=[Guid]::NewGuid();Psql "INSERT INTO stog_user(id)VALUES('$user');INSERT INTO auth_session(id,user_id,access_token_hash,access_expires_at,created_at,absolute_expires_at)VALUES('$session','$user',decode('$hash','hex'),clock_timestamp()+interval'10 minutes',clock_timestamp(),clock_timestamp()+interval'1 day');"|Out-Null
 $parts=(Psql "SELECT id||'|'||encode(convert_to(name,'UTF8'),'hex')||'|'||encode(convert_to(category,'UTF8'),'hex')||'|'||encode(convert_to(region_label,'UTF8'),'hex')FROM place WHERE source_type='SEMAS_STORE' ORDER BY source_key LIMIT 1;")-split'\|';$rowId=$parts[0];$rowName=DecodeHex $parts[1];$rowCategory=DecodeHex $parts[2];$rowRegion=DecodeHex $parts[3];$backend=StartBackend
 $query=[uri]::EscapeDataString($rowName);$region=[uri]::EscapeDataString($rowRegion);$category=[uri]::EscapeDataString($rowCategory);$headers=@{Authorization="Bearer $token"};$search=Invoke-RestMethod -Headers $headers -Uri "http://127.0.0.1:8080/api/places?query=$query&region=$region&category=$category&limit=50";$found=@($search.items|?{$_.place_id-eq$rowId}).Count-eq1;$detail=Invoke-RestMethod -Headers $headers -Uri("http://127.0.0.1:8080/api/places/"+$rowId);$detailSame=$detail.place_id-eq$rowId
 $extensions=Psql "SELECT name||'|'||default_version||'|'||COALESCE(installed_version,'')FROM pg_available_extensions WHERE name IN('pg_trgm','postgis')ORDER BY name;" -Admin
 $result=[ordered]@{result='PASS';datasetId='15083033';snapshot='20260630';archiveSize=352699739;archiveSha256='57aa361544108ff4fc73334f87d2ced61e41fe8638dd70bcd842930f865d2386';entry='Jeju regional CSV';maximumRows=25;firstCardinality=$first;repeatCardinality=$second;stableIdentity=$same;authenticatedSearchFoundExactId=$found;authenticatedDetailSameId=$detailSame;externalCalls=0;retainedDatabaseChanged=$false;availableExtensions=@($extensions-split"`n")};if(-not$same-or$first-ne'25|25|25'-or$second-ne'25|25|25'-or-not$found-or-not$detailSame){throw'real subset postcondition failed'};$result|ConvertTo-Json -Depth 5|Set-Content -Encoding utf8 (Join-Path $artifact 'real-subset-result.json')
}finally{
 StopOwned $backend
 foreach($n in $old.Keys){[Environment]::SetEnvironmentVariable($n,$old[$n],'Process')}
 if($created){Psql "BEGIN;DROP SCHEMA `"$schema`" CASCADE;REVOKE CONNECT ON DATABASE `"$db`" FROM `"$role`";DROP ROLE `"$role`";COMMIT;" -Admin|Out-Null;$remaining=Psql "SELECT(SELECT count(*)FROM pg_roles WHERE rolname='$role')||'|'||(SELECT count(*)FROM pg_namespace WHERE nspname='$schema');" -Admin;$metadataAfter=Psql "SELECT md5(COALESCE(string_agg(row_to_json(x)::text,E'\n' ORDER BY x.rolname),''))FROM(SELECT * FROM pg_roles WHERE rolname<>'$role')x;SELECT md5(COALESCE(string_agg(row_to_json(x)::text,E'\n' ORDER BY x.nspname),''))FROM(SELECT n.nspname,pg_get_userbyid(n.nspowner)owner,n.nspacl::text acl FROM pg_namespace n WHERE n.nspname='public' OR n.nspname~'^task14_')x;SELECT md5(row_to_json(x)::text)FROM(SELECT datname,datdba,datacl::text acl FROM pg_database WHERE datname='$db')x;" -Admin}else{$remaining=$null}
 if(Test-Path $media){Remove-Item -Recurse -Force $media};$receipt=[ordered]@{ownedRoleSchemaRemaining=$remaining;preexistingMetadataRestored=($metadataBefore-eq$metadataAfter);privateMediaRootRemoved=(-not(Test-Path $media));port8080Absent=@(Get-NetTCPConnection -State Listen -LocalPort 8080 -ErrorAction SilentlyContinue).Count-eq0};$receipt|ConvertTo-Json|Set-Content -Encoding utf8 (Join-Path $artifact 'cleanup-receipt.json');$password=$null;if($created-and($remaining-ne'0|0'-or$metadataBefore-ne$metadataAfter)){throw 'cleanup failed'}
}
